<!-- pages/Home.vue -->
<template>
  <div>
    <!-- شريط الـ Stories -->
    <StoryBar 
      :stories="stories" 
      @view-story="openStoryViewer"
      @create-story="openStoryCreator"
      ref="storyBar"
    />

    <!-- باقي المحتوى -->
    <div class="feed-content">
      <!-- منشورات المستخدمين -->
    </div>

    <!-- عارض الـ Stories -->
    <StoryViewer 
      ref="storyViewer" 
      :stories="stories"
    />

    <!-- منشئ الـ Stories -->
    <StoryCreator 
      ref="storyCreator" 
      @story-created="refreshStories"
    />
  </div>
</template>

<script>
import StoryBar from './storyBar.vue';
import StoryViewer from './storyViewer.vue';
import StoryCreator from './storyCreator.vue';

import axios from 'axios'

import serverUrl from '../../config'

export default {
  components: { StoryBar, StoryViewer, StoryCreator },
  data() {
    return {
      stories: []
    }
  },
  created() {
    this.fetchStories();
  },
  methods: {
    async fetchStories() {
      try {
        // const res = await axios.get('http://localhost:3000/api/stories/following', {
        const res = await axios.get(serverUrl + '/api/stories/following', {
          headers: { authorization: localStorage.getItem("token") }
        });
        console.log('stroies for me', res.data)
         this.stories = [...res.data.myStories, ...res.data.friendsStories];

      } catch (error) {
        console.error(error);
      }
    },
    openStoryViewer(index) {
    //   const index = this.stories.findIndex(s => s.userId === story.userId);
      console.log('indexzz: ', index)
      this.$refs.storyViewer.open(index);
    },
    openStoryCreator() {
      this.$refs.storyCreator.open();
    },
    refreshStories(story) {
        console.log('soo: ', story)
        // this.stories.unshift(story)
        this.$refs.storyBar.fetchStories()
      this.fetchStories();
    }
  }
}
</script>