<!-- components/stories/StoryViewer.vue -->
<template>
  <v-dialog v-model="visible" fullscreen transition="fade-transition">
    <div class="story-viewer" @click="handleTap" @touchstart="handleTouchStart" @touchend="handleTouchEnd">
      <!-- شريط التقدم -->
      <div class="progress-bars">
        <div 
          v-for="(slide, index) in currentStory.slides" 
          :key="index"
          class="progress-bar"
        >
          <div 
            class="progress-fill"
            :style="{ width: getProgressWidth(index) + '%' }"
          ></div>
        </div>
      </div>

      <!-- معلومات المستخدم -->
      <div class="story-header">
        <v-avatar size="36" class="mr-2">
          <!-- <v-img :src="currentStory.userImage"></v-img> -->
          <!-- <v-img :src="'http://localhost:3000/profile-image/' + currentStory.userId._id + '.PNG'"></v-img> -->
           
          <v-img :src="`${urls}/profile-image/${currentStory.userId._id}.PNG`"></v-img>
        </v-avatar>
        <div class="user-info">
          <span class="username">{{ currentStory.userId.name }}</span>
          <span class="time">{{ formatTime(currentSlide.createdAt) }}</span>
        </div>
        <v-btn icon dark @click.stop="close">
          <v-icon>mdi-close</v-icon>
        </v-btn>

        <div v-if="isOwner" class="viewers-btn" @click.stop="showViewers = true">
        <v-icon color="white" size="20">mdi-eye</v-icon>
        <span>{{ currentStory.seenBy.length || 0 }}</span>
      </div>
      </div>
 
      <!-- محتوى الـ Story -->
       <!--  :src="'http://localhost:3000' + currentSlide.url"  -->
      <div class="story-content">
        <div>
         
        </div>
        <img 
          v-if="currentSlide._doc.type === 'image'" 
          :src="getImageUrl( currentSlide._doc.url)" 
          class="story-media"
        >
        <video 
          v-else-if="currentSlide._doc.type === 'video'" 
          :src="currentSlide.url" 
          autoplay 
          muted
          class="story-media"
          @ended="nextSlide"
        ></video>
        <div 
          v-else-if="currentSlide._doc.type === 'text'" 
          class="story-text"
          :style="{ backgroundColor: currentSlide._doc.backgroundColor }"
        >
          <p>{{ currentSlide._doc.text }}</p>
        </div>
        
      </div>

      <!-- أزرار التنقل -->
      <div class="nav-zones">
        <div class="nav-left" @click.stop="prevSlide"></div>
        <div class="nav-right" @click.stop="nextSlide"></div>
      </div>

      <!-- زر الرد -->
      <!-- <div class="story-footer">
        <v-text-field
          v-model="replyText"
          placeholder="رد على الـ Story..."
          outlined
          rounded
          dense
          dark
          hide-details
          class="reply-input"
          @keyup.enter="sendReply"
          append-icon="mdi-send"
          @click:append="sendReply"
        ></v-text-field>
      </div> -->
    </div>
     <v-bottom-sheet v-model="showViewers" max-width="500">
      <v-card class="viewers-sheet">
        <v-card-title class="headline">
        Views
          <v-spacer></v-spacer>
          <v-btn icon @click="showViewers = false">
            <v-icon>mdi-close</v-icon>
          </v-btn>
        </v-card-title>
        
        <v-card-text>
          <v-list v-if="currentStory.seenBy.length">
            <v-list-item v-for="viewer in currentStory.seenBy" :key="viewer._id">
              <v-list-item-avatar>
                <v-img 
                  :src="getViewrsUrl(viewer)" 
                  @error="handleImageError"
                ></v-img>
              </v-list-item-avatar>
              
              <v-list-item-content>
                <v-list-item-title>{{ viewer.name }}</v-list-item-title>
              </v-list-item-content>
              
              <v-list-item-action>
                <v-icon small color="green">mdi-check-all</v-icon>
              </v-list-item-action>
            </v-list-item>
          </v-list>
          
          <div v-else class="no-viewers text-center pa-4">
            <v-icon size="48" color="grey">mdi-eye-off</v-icon>
            <p class="grey--text">No views yet</p>
          </div>
        </v-card-text>
      </v-card>
    </v-bottom-sheet>
  </v-dialog>
</template>

<script>
import axios from 'axios';

import serverUrl from '../../config'

export default {
  props: {
    stories: Array,
    initialIndex: {
      type: Number,
      default: 0,
     
    }
  },
  data() {
    return {
      visible: false,
      currentStoryIndex: 0,
      currentSlideIndex: 0,
      progress: 0,
      timer: null,
      slideDuration: 5000, // 5 ثواني لكل شريحة
      replyText: '',
      touchStartX: 0,
      showViewers: false,
       urls: serverUrl
    }
  },
  computed: {
    currentStory() {
      return this.stories[this.currentStoryIndex] || { slides: [] };
    },
    currentSlide() {
      console.log('coco: ', this.currentStory.slides[this.currentSlideIndex])
      return this.currentStory.slides[this.currentSlideIndex] || {};
    },
     isOwner() {  // ✅ هل المستخدم الحالي هو صاحب القصة؟
      const userID = localStorage.getItem('userID');
      const storyOwnerId = this.currentStory.userId?._id || this.currentStory.userId;
      return storyOwnerId?.toString() === userID;
    },
    totalSlides() {
      return this.currentStory.slides?.length || 0;
    }
  },
  watch: {
    visible(val) {
      if (val) {
        this.startProgress();
      } else {
        this.stopProgress();
      }
    }
  },
  methods: {
    open(index = 0) {
      this.currentStoryIndex = index;
      this.currentSlideIndex = 0;
      this.progress = 0;
      this.visible = true;
      this.markAsSeen();
    },
    close() {
      this.visible = false;
      this.stopProgress();
    },
    startProgress() {
      this.stopProgress();
      this.timer = setInterval(() => {
        this.progress += 100 / (this.slideDuration / 100);
        if (this.progress >= 100) {
          this.nextSlide();
        }
      }, 100);
    },
    stopProgress() {
      if (this.timer) {
        clearInterval(this.timer);
        this.timer = null;
      }
    },
    getProgressWidth(index) {
      if (index < this.currentSlideIndex) return 100;
      if (index > this.currentSlideIndex) return 0;
      return this.progress;
    },
    nextSlide() {
      this.stopProgress();
      this.progress = 0;
      
      if (this.currentSlideIndex < this.totalSlides - 1) {
        this.currentSlideIndex++;
        this.startProgress();
      } else {
        // ✅ ثم الانتقال للقصة التالية
        this.nextStory();
      }
    },
    prevSlide() {
      this.stopProgress();
      this.progress = 0;
      
      if (this.currentSlideIndex > 0) {
        this.currentSlideIndex--;
        this.startProgress();
      } else {
        this.prevStory();
      }
    },
    nextStory() {
      if (this.currentStoryIndex < this.stories.length - 1) {
        this.currentStoryIndex++;
        this.currentSlideIndex = 0;
        this.markAsSeen();
        this.startProgress();
      } else {
        this.close();
      }
    },
    prevStory() {
      if (this.currentStoryIndex > 0) {
        this.currentStoryIndex--;
        this.currentSlideIndex = 0;
        this.startProgress();
      }
    },
    handleTap(event) {
      const width = window.innerWidth;
      const clickX = event.clientX;
      
      if (clickX < width * 0.3) {
        this.prevSlide();
      } else if (clickX > width * 0.7) {
        this.nextSlide();
      } else {
        // النقر في المنتصف: إيقاف/تشغيل
        if (this.timer) {
          this.stopProgress();
        } else {
          this.startProgress();
        }
      }
    },
    handleTouchStart(e) {
      this.touchStartX = e.touches[0].clientX;
      this.stopProgress();
    },
    handleTouchEnd(e) {
      const diff = this.touchStartX - e.changedTouches[0].clientX;
      if (Math.abs(diff) > 50) {
        if (diff > 0) this.nextStory();
        else this.prevStory();
      } else {
        this.startProgress();
      }
    },
    async markAsSeen() {
       try {
        // ✅ تسجيل مشاهدة القصة الرئيسية فقط
        // await axios.post('http://localhost:3000/api/stories/seen', {
        await axios.post(serverUrl + '/api/stories/seen', {
          storyId: this.currentStory._id
        }, {
          headers: { authorization: localStorage.getItem("token") }
        });
      } catch (error) {
        console.error('Error marking story as seen:', error);
      }
    },
    async sendReply() {
      if (!this.replyText.trim()) return;
      
      try {
        await this.$axios.post('/api/stories/reply', {
          storyId: this.currentStory._id,
          slideIndex: this.currentSlideIndex,
          text: this.replyText
        }, {
          headers: { authorization: localStorage.getItem("token") }
        });
        
        this.replyText = '';
        this.$toast.success('تم إرسال الرد');
      } catch (error) {
        console.error('Error sending reply:', error);
      }
    },
    formatTime(timestamp) {
      if (!timestamp) return '';
      const date = new Date(timestamp);
      const now = new Date();
      const diffMs = now - date;
      const diffSec = Math.floor(diffMs / 1000);
      const diffMin = Math.floor(diffSec / 60);
      const diffHour = Math.floor(diffMin / 60);
      const diffDay = Math.floor(diffHour / 24);

      if (diffMin < 1) return 'Just now';
      if (diffMin < 60) return `${diffMin}m ago`;
      if (diffHour < 24) return `${diffHour}h ago`;
      if (diffDay < 7) return `${diffDay}d ago`;
      if (diffDay < 30) return `${Math.floor(diffDay / 7)}w ago`;
      if (diffDay < 365) return `${Math.floor(diffDay / 30)}mo ago`;
      return `${Math.floor(diffDay / 365)}y ago`;
    },
    getImageUrl(path) {
      console.log('the id: ', path)
      const token = localStorage.getItem('token');
      
      // إضافة التوكن كـ query parameter
      // return `http://localhost:3000${path}?token=${token}`;
      return `${serverUrl}${path}?token=${token}`;
    },
    getViewrsUrl(viewer) {
      const token = localStorage.getItem('token');
      const userId = viewer._id || viewer.id;
      // return `http://localhost:3000/profile-image/${userId}.PNG?token=${token}`;
      return `${serverUrl}/profile-image/${userId}.PNG?token=${token}`;
    },
    handleImageError() {

    }
  }
}
</script>

<style scoped>
.story-viewer {
  position: relative;
  width: 100%;
  height: 100vh;
  background: black;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.progress-bars {
  display: flex;
  gap: 4px;
  padding: 12px 12px 0;
  z-index: 10;
}

.progress-bar {
  flex: 1;
  height: 3px;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 2px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: white;
  transition: width 0.1s linear;
}

.story-header {
  display: flex;
  align-items: center;
  padding: 12px;
  color: white;
  z-index: 10;
}

.user-info {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.username {
  font-weight: 600;
  font-size: 0.9rem;
}

.time {
  font-size: 0.75rem;
  opacity: 0.8;
}

.story-content {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.story-media {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}

.story-text {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  text-align: center;
}

.story-text p {
  color: white;
  font-size: 1.5rem;
  font-weight: 600;
  text-shadow: 0 2px 4px rgba(0,0,0,0.3);
}

.nav-zones {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 80px;
  display: flex;
  z-index: 5;
}

.nav-left, .nav-right {
  flex: 1;
}

.story-footer {
  padding: 16px;
  z-index: 10;
}

.reply-input {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 24px;
}

/* Responsive */
@media (max-width: 768px) {
  .story-text p {
    font-size: 1.2rem;
  }
}


.viewers-btn {
  position: absolute;
  bottom: 80px;
  right: 16px;
  background: rgba(0, 0, 0, 0.5);
  color: white;
  padding: 8px 16px;
  border-radius: 20px;
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  z-index: 20;
  backdrop-filter: blur(4px);
}

.viewers-btn:hover {
  background: rgba(0, 0, 0, 0.7);
}

.viewers-sheet {
  border-radius: 16px 16px 0 0;
  max-height: 70vh;
}

.no-viewers {
  color: #999;
}
</style>