<template>
  <div :key="localReRenderComponent">
    <!-- زر إنشاء منشور -->
    <transition name="fade-scale">
      <div 
        v-if="!isPosting"
        :style="buttonStyle"
        class="floating-button"
      >
        <v-tooltip bottom>
          <template v-slot:activator="{ on, attrs }">
            <v-btn
              class="create-post-btn"
              large
              fab
              color="primary"
              v-bind="attrs"
              v-on="{...on, click: startSteps}"
              elevation="8"
            >
              <v-icon large>mdi-pencil-plus</v-icon>
            </v-btn>
          </template>
          <span>Create new post</span>
        </v-tooltip>
      </div>
    </transition>

    <!-- Progress Circle أثناء النشر -->
    <transition name="scale">
      <div 
        v-if="isPosting && !applyPost"
        :style="progressStyle"
        class="progress-wrapper"
      >
        <v-hover v-slot="{  }">
          <v-progress-circular
            :rotate="180"
            :size="100"
            :width="12"
            :value="progressValue"
            :color="progressColor"
            class="progress-circle"
          >
            <span class="progress-text">{{ progressValue }}%</span>
          </v-progress-circular>
        </v-hover>
      </div>
    </transition>

    <!-- نموذج إنشاء المنشور -->
    <transition name="slide-fade">
      <div v-if="isPosting && !applyPost" class="post-form-container">
        <v-sheet
          class="post-sheet"
          color="grey lighten-4"
          elevation="12"
          rounded="lg"
        >
          <!-- Header مع عنوان -->
          <div class="sheet-header">
            <h2 class="text-h5 font-weight-bold primary--text">
              <v-icon large color="primary" class="mr-2">mdi-post-outline</v-icon>
             Create new post
            </h2>
            <v-btn 
              icon 
              @click="reset" 
              class="close-btn"
              small
            >
              <v-icon>mdi-close</v-icon>
            </v-btn>
          </div>

          <v-divider></v-divider>

          <!-- Vertical Stepper محسن -->
          <v-stepper
            v-model="currentStep"
            vertical
            class="custom-stepper"
          >
            <!-- الخطوة 1: العنوان -->
            <v-stepper-step
              :complete="currentStep > 1"
              step="1"
              editable
              :rules="[() => !titleError]"
              class="stepper-step"
            >
              <span class="step-title">Title</span>
              <small class="step-desc">Enter post title</small>
            </v-stepper-step>

            <v-stepper-content step="1" class="step-content">
              <v-text-field
                v-model="postTitle"
                label="Post title"
                placeholder="Write a catchy title .."
                counter="25"
                :error-messages="titleErrorMessage"
                :success="titleValid"
                color="primary"
                outlined
                dense
                class="title-input"
                @input="validateTitle"
                @keyup.enter="goToStep(2)"
              >
                <template v-slot:prepend>
                  <v-icon color="primary">mdi-format-title</v-icon>
                </template>
              </v-text-field>

              <div class="step-actions">
                <v-btn
                  color="primary"
                  @click="goToStep(2)"
                  :disabled="!titleValid"
                  elevation="2"
                >
                  Continue
                  <v-icon right>mdi-arrow-right</v-icon>
                </v-btn>
              </div>
            </v-stepper-content>

            <!-- الخطوة 2: الصورة -->
            <v-stepper-step
              :complete="currentStep > 2"
              step="2"
              :rules="[() => imageValid]"
              class="stepper-step"
            >
              <span class="step-title">Photo</span>
              <small class="step-desc">Choose a post image</small>
            </v-stepper-step>

            <v-stepper-content step="2" class="step-content">
              <v-card
                class="image-upload-card"
                :class="{ 'has-image': selectedFile }"
                @click="$refs.fileInput.click()"
                outlined
                hover
              >
                <div v-if="!selectedFile" class="upload-placeholder">
                  <v-icon size="64" color="primary lighten-2">mdi-image-plus</v-icon>
                  <span class="upload-text">Click to choose an image</span>
                  <span class="upload-hint">jpg, png, gif (max 5MB)</span>
                </div>

                <div v-else class="image-preview-wrapper">
                  <img
                    ref="previewImage"
                    class="image-preview"
                    :src="imagePreview"
                    alt="Preview"
                  />
                  <div class="image-overlay">
                    <v-btn
                      icon
                      small
                      color="white"
                      @click.stop="clearImage"
                    >
                      <v-icon>mdi-close</v-icon>
                    </v-btn>
                  </div>
                </div>

                <input
                  ref="fileInput"
                  type="file"
                  accept="image/*"
                  class="hidden-input"
                  @change="handleImageSelect"
                />
              </v-card>

              <div class="step-actions">
                <v-btn
                  text
                  @click="goToStep(1)"
                  class="mr-2"
                >
                  <v-icon left>mdi-arrow-left</v-icon>
                  Previous
                </v-btn>
                <v-btn
                  color="primary"
                  @click="goToStep(3)"
                  :disabled="!imageValid"
                  elevation="2"
                >
                  Continue
                  <v-icon right>mdi-arrow-right</v-icon>
                </v-btn>
              </div>
            </v-stepper-content>

            <!-- الخطوة 3: معاينة -->
            <v-stepper-step
              :complete="currentStep > 3"
              step="3"
              class="stepper-step"
            >
              <span class="step-title">Preview</span>
              <small class="step-desc">Review your post before publishing</small>
            </v-stepper-step>

            <v-stepper-content step="3" class="step-content">
              <PostReview
                :image="imagePreview"
                :name="postTitle"
                :ownerName="username"
                class="preview-card"
              />

              <div class="step-actions">
                <v-btn
                  text
                  @click="goToStep(2)"
                  class="mr-2"
                >
                  <v-icon left>mdi-arrow-left</v-icon>
                  Previous
                </v-btn>
                <v-btn
                  color="primary"
                  @click="goToStep(4)"
                  elevation="2"
                >
                  Continue
                  <v-icon right>mdi-arrow-right</v-icon>
                </v-btn>
              </div>
            </v-stepper-content>

            <!-- الخطوة 4: النشر -->
            <v-stepper-step step="4" class="stepper-step">
              <span class="step-title">Publish</span>
              <small class="step-desc">Share your post with the world</small>
            </v-stepper-step>

            <v-stepper-content step="4" class="step-content">
              <v-alert
                type="info"
                colored-border
                border="left"
                elevation="2"
                class="publish-alert"
              >
                <div class="d-flex align-center">
                  <v-icon large color="info" class="mr-3">mdi-information</v-icon>
                  <div>
                    <h3 class="text-subtitle-1 font-weight-bold">You're about to publish!</h3>
                    <p class="text-body-2 mb-0">Make sure your content is accurate before publishing</p>
                  </div>
                </div>
              </v-alert>

              <div class="step-actions">
                <v-btn
                  text
                  @click="goToStep(3)"
                  class="mr-2"
                >
                  <v-icon left>mdi-arrow-left</v-icon>
                  Preview
                </v-btn>
                <v-btn
                  color="success"
                  @click="publishPost"
                  :loading="postLoading"
                  elevation="2"
                  large
                >
                  <v-icon left>mdi-check</v-icon>
                 Publish the post
                </v-btn>
                <v-btn
                  text
                  color="grey"
                  @click="reset"
                  class="mr-2"
                >
                  Cancel
                </v-btn>
              </div>
            </v-stepper-content>
          </v-stepper>
        </v-sheet>
      </div>
    </transition>

    <!-- مؤشر تحميل أثناء النشر -->
    <transition name="fade">
      <div v-if="applyPost" class="loading-overlay">
        <v-card class="loading-card" elevation="24">
          <v-progress-circular
            indeterminate
            size="64"
            color="primary"
          ></v-progress-circular>
          <h3 class="text-h6 mt-4">Publishing the post.....</h3>
          <p class="text-body-2 grey--text">This may take a few seconds</p>
        </v-card>
      </div>
    </transition>

    <!-- رسالة نجاح (Snackbar) -->
    <v-snackbar
      v-model="showSuccess"
      :timeout="4000"
      color="success"
      elevation="24"
      right
      top
    >
      <v-icon left>mdi-check-circle</v-icon>
      {{ successMessage }}
      <template v-slot:action="{ attrs }">
        <v-btn
          text
          v-bind="attrs"
          @click="showSuccess = false"
        >
          Close
        </v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import serverUrl from '../../config';
import PostReview from '../post/postReview.vue';
import { mapGetters, mapMutations } from 'vuex';
import { eventBus } from '../../main';
import axios from 'axios';
import io from 'socket.io-client';

export default {
  name: 'CreatePost',
  
  components: {
    PostReview
  },

  props: {
    position: {
      type: String,
      default: 'fixed'
    },
    maxWidth: {
      type: Number,
      default: 800
    },
    marginLeft: {
      type: String,
      default: '20px'
    }
  },

  data() {
    return {
      // حالة النموذج
      currentStep: 1,
      postTitle: '',
      selectedFile: null,
      imagePreview: null,
      
      // حالة النشر
      isPosting: false,
      postLoading: false,
      applyPost: false,
      
      // حالة التحقق
      titleError: false,
      titleErrorMessage: '',
      imageValid: false,
      
      // تقدم النشر
      progressValue: 0,
      
      // حالة إعادة الرسم
      localReRenderComponent: 0,
      
      // رسائل النجاح
      showSuccess: false,
      successMessage: '',
      
      // Socket.io
      socket: io(serverUrl, {
        query: { token: localStorage.getItem('token') }
      }),
      
      urls: serverUrl
    };
  },

  computed: {
    ...mapGetters({
      username: 'getUsername',
      renderComponent: 'getrerendercomponent'
    }),

    buttonStyle() {
      return {
        'margin-left': this.marginLeft,
        'margin-top': '-55px',
        'position': this.position,
        'z-index': 100
      };
    },

    progressStyle() {
      return {
        'margin-left': this.marginLeft,
        'margin-top': '-55px',
        'position': this.position,
        'z-index': 100
      };
    },

    progressColor() {
      if (this.progressValue === 100) return 'success';
      if (this.progressValue >= 50) return 'info';
      return 'primary';
    },

    titleValid() {
      return this.postTitle && this.postTitle.length <= 25 && this.postTitle.length >= 3;
    }
  },

  methods: {
    ...mapMutations({
      setpostProgress: 'setpostProgress'
    }),

    // بدء عملية إنشاء المنشور
    startSteps() {
      this.isPosting = true;
      this.currentStep = 1;
      this.progressValue = 0;
    },

    // التنقل بين الخطوات
    goToStep(step) {
      if (step === 2 && !this.validateTitle()) {
        this.showValidationError('الرجاء إدخال عنوان صحيح');
        return;
      }
      
      if (step === 3 && !this.selectedFile) {
        this.showValidationError('الرجاء اختيار صورة');
        return;
      }

      this.currentStep = step;
      this.updateProgress();
      this.scrollToStep(step);
    },

    // التحقق من صحة العنوان
    validateTitle() {
      if (!this.postTitle) {
        this.titleError = true;
        this.titleErrorMessage = 'Title required';
        return false;
      }
      
      if (this.postTitle.length > 25) {
        this.titleError = true;
        this.titleErrorMessage = 'Title is too long (max 25 characters)';
        return false;
      }
      
      if (this.postTitle.length < 3) {
        this.titleError = true;
        this.titleErrorMessage = 'العنوان قصير جداً (الحد الأدنى 3 أحرف)';
        return false;
      }
      
      this.titleError = false;
      this.titleErrorMessage = '';
      return true;
    },

    // معالجة اختيار الصورة
    handleImageSelect(event) {
      const file = event.target.files[0];
      
      if (!file) return;
      
      // التحقق من نوع الملف
      if (!file.type.startsWith('image/')) {
        this.showValidationError('الرجاء اختيار ملف صورة صالح');
        return;
      }
      
      // التحقق من حجم الملف (5MB كحد أقصى)
      if (file.size > 5 * 1024 * 1024) {
        this.showValidationError('حجم الصورة كبير جداً (الحد الأقصى 5MB)');
        return;
      }
      
      this.selectedFile = file;
      this.imageValid = true;
      
      // إنشاء معاينة
      const reader = new FileReader();
      reader.onload = (e) => {
        this.imagePreview = e.target.result;
      };
      reader.readAsDataURL(file);
    },

    // مسح الصورة المحددة
    clearImage() {
      this.selectedFile = null;
      this.imagePreview = null;
      this.imageValid = false;
      this.$refs.fileInput.value = '';
    },

    // تحديث شريط التقدم
    updateProgress() {
      switch (this.currentStep) {
        case 2:
          this.progressValue = 25;
          break;
        case 3:
          this.progressValue = 50;
          break;
        case 4:
          this.progressValue = 75;
          break;
        default:
          this.progressValue = 0;
      }
    },

    // التمرير إلى الخطوة المحددة
    scrollToStep(step) {
      setTimeout(() => {
        const stepElement = document.querySelector(`.v-stepper__step--${step}`);
        if (stepElement) {
          stepElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    },

    // نشر المنشور
    async publishPost() {
      if (!this.selectedFile || !this.postTitle) {
        this.showValidationError('الرجاء إكمال جميع البيانات');
        return;
      }

      this.postLoading = true;
      this.progressValue = 90;
      this.applyPost = true;
      this.setpostProgress(true);

      const formData = new FormData();
      formData.append('file', this.selectedFile);
      formData.append('data', this.postTitle);

      try {
        const response = await axios.post(
          `${this.urls}/post/new-post`,
          formData,
          {
            headers: { 
              authorization: localStorage.getItem('token'),
              'Content-Type': 'multipart/form-data'
            }
          }
        );

        if (response.data.success) {
          this.progressValue = 100;
          this.socket.emit('new-post', response.data);
          
          // إظهار رسالة نجاح
          this.successMessage = `تم نشر "${this.postTitle}" بنجاح`;
          this.showSuccess = true;
          
          // إعادة تعيين النموذج
          setTimeout(() => {
            this.reset();
            this.$emit('post-created', response.data.post);
          }, 1500);
        }
      } catch (error) {
        console.error('خطأ في نشر المنشور:', error);
        this.showValidationError('حدث خطأ أثناء النشر. الرجاء المحاولة مرة أخرى');
        this.progressValue = 75;
      } finally {
        this.postLoading = false;
        this.applyPost = false;
        this.setpostProgress(false);
      }
    },

    // إعادة تعيين النموذج
    reset() {
      this.currentStep = 1;
      this.postTitle = '';
      this.selectedFile = null;
      this.imagePreview = null;
      this.isPosting = false;
      this.progressValue = 0;
      this.titleError = false;
      this.titleErrorMessage = '';
      this.imageValid = false;
      
      // إعادة تعيين حقل الملف
      if (this.$refs.fileInput) {
        this.$refs.fileInput.value = '';
      }
      
      // زيادة قيمة المفتاح لإعادة رسم المكون
      this.localReRenderComponent += 1;
    },

    // إظهار رسالة خطأ
    showValidationError(message) {
      this.$emit('error', message);
      // يمكن استخدام toast أو أي نظام إشعارات هنا
      console.error(message);
    }
  },

  watch: {
    currentStep() {
      this.updateProgress();
    },

    postTitle() {
      this.validateTitle();
    }
  },

  mounted() {
    // استماع لأحداث التمرير من الـ eventBus
    eventBus.$on('marginTopCustomPost', (margin) => {
      window.scrollTo({
        top: margin,
        behavior: 'smooth'
      });
    });
  },

  beforeDestroy() {
    // تنظيف الأحداث
    eventBus.$off('marginTopCustomPost');
    if (this.socket) {
      this.socket.disconnect();
    }
  }
};
</script>

<style scoped>
/* أنيميشنات */
.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.3s ease;
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}

.fade-scale-enter-active {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.fade-scale-leave-active {
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.fade-scale-enter-from,
.fade-scale-leave-to {
  opacity: 0;
  transform: scale(0.8);
}

.scale-enter-active {
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.scale-leave-active {
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.scale-enter-from,
.scale-leave-to {
  opacity: 0;
  transform: scale(0.5);
}

.slide-fade-enter-active {
  transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.slide-fade-leave-active {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.slide-fade-enter-from,
.slide-fade-leave-to {
  opacity: 0;
  transform: translateY(30px);
}

/* زر إنشاء منشور */
.floating-button {
  position: fixed;
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
  top: 50%;
  transform: translateY(50%);
}

.create-post-btn {
  background: linear-gradient(135deg, #e91e63 0%, #c2185b 100%) !important;
  transition: all 0.3s ease !important;
  box-shadow: 0 4px 15px rgba(233, 30, 99, 0.4) !important;
}

.create-post-btn:hover {
  transform: scale(1.1) rotate(90deg);
  box-shadow: 0 6px 20px rgba(233, 30, 99, 0.6) !important;
}

/* شريط التقدم */
.progress-wrapper {
  position: fixed;
  z-index: 1000;
  cursor: pointer;
}

.progress-circle {
  background: white;
  border-radius: 50%;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
}

.progress-text {
  font-weight: bold;
  font-size: 1.2rem;
}

/* نموذج المنشور */
.post-form-container {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 90%;
  max-width: 800px;
  max-height: 90vh;
  overflow-y: auto;
  z-index: 1001;
}

.post-sheet {
  background: white !important;
  border-radius: 16px !important;
  overflow: hidden;
}

.sheet-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px;
  background: linear-gradient(135deg, #f5f5f5 0%, #eeeeee 100%);
}

.close-btn {
  transition: transform 0.3s ease;
}

.close-btn:hover {
  transform: rotate(90deg);
}

/* Stepper محسن */
.custom-stepper {
  background: transparent !important;
  padding: 24px;
}

.stepper-step {
  padding: 16px !important;
  transition: background-color 0.3s ease;
}

.stepper-step:hover {
  background-color: rgba(233, 30, 99, 0.05);
}

.step-title {
  font-weight: 600;
  font-size: 1.1rem;
  display: block;
  color: #333;
}

.step-desc {
  font-size: 0.85rem;
  color: #999;
  display: block;
}

.step-content {
  padding: 20px 0 20px 40px !important;
}

.step-actions {
  margin-top: 20px;
  display: flex;
  justify-content: flex-end;
}

/* تحسينات حقول الإدخال */
.title-input {
  max-width: 500px;
}

.title-input.v-text-field--outlined >>> fieldset {
  border-width: 2px;
}

.title-input.v-text-field--outlined:hover >>> fieldset {
  border-color: #e91e63 !important;
}

/* رفع الصورة */
.image-upload-card {
  min-height: 250px;
  cursor: pointer;
  transition: all 0.3s ease;
  border: 2px dashed #ddd;
  margin-bottom: 16px;
  overflow: hidden;
  position: relative;
}

.image-upload-card:hover {
  border-color: #e91e63;
  background-color: rgba(233, 30, 99, 0.02);
}

.image-upload-card.has-image {
  border: none;
  padding: 0;
}

.upload-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 250px;
  gap: 10px;
}

.upload-text {
  font-size: 1rem;
  color: #666;
}

.upload-hint {
  font-size: 0.8rem;
  color: #999;
}

.image-preview-wrapper {
  position: relative;
  width: 100%;
  height: 250px;
  overflow: hidden;
}

.image-preview {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.image-preview-wrapper:hover .image-preview {
  transform: scale(1.05);
}

.image-overlay {
  position: absolute;
  top: 10px;
  right: 10px;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.image-preview-wrapper:hover .image-overlay {
  opacity: 1;
}

.hidden-input {
  display: none;
}

/* معاينة المنشور */
.preview-card {
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  margin-bottom: 20px;
}

/* تحميل بعد النشر */
.loading-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(255, 255, 255, 0.9);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 2000;
  backdrop-filter: blur(5px);
}

.loading-card {
  padding: 40px;
  text-align: center;
  border-radius: 16px !important;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.05);
  }
  100% {
    transform: scale(1);
  }
