<!-- components/stories/StoryBar.vue -->
<template>
  <div class="story-bar">
    <!-- إضافة Story جديدة -->
    <div class="story-item add-story" @click="$emit('create-story')">
      <div class="story-ring add-ring">
        <v-avatar size="56" class="add-avatar">
          <v-icon size="28" color="primary">mdi-plus</v-icon>
        </v-avatar>
      </div>
      <span class="story-username">Add</span>
    </div>

    <!-- ✅ قصة واحدة لكل مستخدم (مهما كانت الشرائح) -->
    <div 
      v-for="(story, index) in groupedStories" 
      :key="story.userId._id"
      class="story-item"
      @click="$emit('view-story', index)"
    >
      <div 
        class="story-ring"
        :class="{ 'seen': isAllSeen(story), 'unseen': !isAllSeen(story) }"
      >
        <v-avatar size="56">
          <v-img 
            :src="getImageUrl(story.userId._id)" 
            @error="handleImageError"
          ></v-img>
        </v-avatar>
      </div>
      
      <!-- ✅ عدد الشرائح -->
      <span class="story-username">{{ story.username }}</span>
      <span v-if="story.slides.length > 1" class="slides-count">
        {{ story.slides.length }}
      </span>
    </div>
  </div>
</template>

<script>
import serverUrl from '@/config';
import axios from 'axios'

export default {
  props: {
    stories: {
      type: Array,
      default: () => []
    }
  },
  computed: {
    // ✅ القصص مُجمَّعة مسبقاً من الـ Backend
    groupedStories() {
      return this.stories;
    }
  },
  methods: {
    isAllSeen(story) {
      const userID = localStorage.getItem('userID');
      // ✅ التحقق من جميع المشاهدين في جميع الشرائح
      return story.seenBy?.some(v => v._id.toString() === userID);
    },
    getImageUrl(userId) {
      const token = localStorage.getItem('token');
      return `${serverUrl}/profile-image/${userId}.PNG?token=${token}`;
    },
    handleImageError(event) {
      event.target.src = `${serverUrl}/profile-image/avatar.png`;
    },
    async fetchStories() {
      try {
        const res = await axios.get('http://localhost:3000/api/stories/following', {
          headers: { authorization: localStorage.getItem("token") }
        });
       this.stories = [...res.data.myStories, ...res.data.friendsStories];
      } catch (error) {
        console.error('Error fetching stories:', error);
      }
    },
  }
}
</script>

<style scoped>
.story-bar {
  display: flex;
  gap: 12px;
  padding: 12px 16px;
  background: white;
  border-bottom: 1px solid #e0e0e0;
  overflow-x: auto;
  scrollbar-width: none;
}

.story-bar::-webkit-scrollbar {
  display: none;
}

.story-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  flex-shrink: 0;
  min-width: 72px;
  position: relative;
}

.story-ring {
  padding: 3px;
  border-radius: 50%;
  background: linear-gradient(45deg, #f09433, #e6683c, #dc2743, #cc2366, #bc1888);
}

.story-ring.seen {
  background: #e0e0e0;
}

.story-ring.unseen {
  animation: pulse 2s infinite;
}

.add-ring {
  background: transparent;
  border: 2px dashed #ccc;
}

.add-avatar {
  background-color: #f5f5f5;
}

.story-username {
  font-size: 0.75rem;
  margin-top: 4px;
  max-width: 64px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: center;
}

.slides-count {
  position: absolute;
  top: 0;
  right: 0;
  background: #e1306c;
  color: white;
  font-size: 0.65rem;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

@keyframes pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.05); }
}
</style>