<!-- components/stories/StoryCreator.vue -->
<template>
  <v-dialog v-model="visible" max-width="500" persistent>
    <v-card class="story-creator">
      <v-card-title class="headline">Create Story</v-card-title>
      
      <v-card-text>
        <!-- اختيار النوع -->
        <v-tabs v-model="tab" grow>
          <v-tab>Photo</v-tab>
          <v-tab>text</v-tab>
        </v-tabs>

        <v-tabs-items v-model="tab">
          <!-- تبويب الصورة -->
          <v-tab-item>
            <div class="upload-area" @click="$refs.fileInput.click()">
              <input 
                ref="fileInput" 
                type="file" 
                accept="image/*,video/*" 
                hidden 
                @change="handleFileSelect"
              >
              <div v-if="!preview" class="upload-placeholder">
                <v-icon size="48" color="grey">mdi-cloud-upload</v-icon>
                <p>Tap to choose a photo or video</p>
              </div>
              <img v-else-if="fileType === 'image'" :src="preview" class="preview">
              <video v-else :src="preview" controls class="preview"></video>
            </div>
          </v-tab-item>

          <!-- تبويب النص -->
          <v-tab-item>
            <v-textarea
              v-model="textContent"
              placeholder="Write something ..."
              outlined
              rows="4"
              counter="200"
            ></v-textarea>
            
            <div class="color-picker">
              <div 
                v-for="color in colors" 
                :key="color"
                class="color-option"
                :style="{ backgroundColor: color }"
                :class="{ selected: selectedColor === color }"
                @click="selectedColor = color"
              ></div>
            </div>
          </v-tab-item>
        </v-tabs-items>
      </v-card-text>

      <v-card-actions>
        <v-spacer></v-spacer>
        <v-btn text @click="close">Cancel</v-btn>
        <v-btn color="primary" :loading="uploading" @click="publish" :disabled="!canPublish">
          Deploy
        </v-btn>
      </v-card-actions>
    </v-card>
  </v-dialog>
  
</template>

<script>
import axios from 'axios'

import serverUrl from '../../config'

export default {
  data() {
    return {
      visible: false,
      tab: 0,
      file: null,
      preview: null,
      fileType: 'image',
      textContent: '',
      selectedColor: '#E1306C',
      uploading: false,
      colors: ['#E1306C', '#F77737', '#FCAF45', '#833AB4', '#5851DB', '#405DE6', '#1DB954', '#000000']
    }
  },
  computed: {
    canPublish() {
      if (this.tab === 0) return !!this.file;
      return this.textContent.trim().length > 0;
    }
  },
  methods: {
    open() {
      this.visible = true;
      this.reset();
    },
    close() {
      this.visible = false;
    },
    reset() {
      this.tab = 0;
      this.file = null;
      this.preview = null;
      this.textContent = '';
    },
    handleFileSelect(event) {
      const file = event.target.files[0];
      if (!file) return;
      
      this.file = file;
      this.fileType = file.type.startsWith('video') ? 'video' : 'image';
      this.preview = URL.createObjectURL(file);
    },
    async publish() {
      this.uploading = true;
      
      try {
        const formData = new FormData();
        formData.append('type', this.tab === 0 ? this.fileType : 'text');
        
        if (this.tab === 0) {
          formData.append('media', this.file);
        } else {
          formData.append('text', this.textContent);
          formData.append('backgroundColor', this.selectedColor);
        }

        // let res = await axios.post('http://localhost:3000/api/stories/', formData, {
        let res = await axios.post(serverUrl + '/api/stories/', formData, {
          headers: {
            authorization: localStorage.getItem("token"),
            'Content-Type': 'multipart/form-data'
          }
        });

        // this.$toast.success('تم نشر الـ Story بنجاح!');
          this.$notify({
              title: 'New Story',
              text: 'new story',
              type: 'success'
          });
        this.close();
        console.log('asd',res.data.story)
        this.$emit('story-created', res.data.story);
      } catch (error) {
        console.error('Error publishing story:', error);
        // this.$toast.error('حدث خطأ أثناء النشر');
        this.$notify({
              title: 'error publishing story',
              text: 'new story',
              type: 'error'
          });
      } finally {
        this.uploading = false;
      }
    }
  }
}
</script>

<style scoped>
.story-creator {
  border-radius: 16px;
}

.upload-area {
  border: 2px dashed #ccc;
  border-radius: 12px;
  padding: 40px;
  text-align: center;
  cursor: pointer;
  margin-top: 16px;
  transition: border-color 0.3s;
}

.upload-area:hover {
  border-color: #E1306C;
}

.upload-placeholder p {
  margin-top: 12px;
  color: #666;
}

.preview {
  max-width: 100%;
  max-height: 300px;
  border-radius: 8px;
}

.color-picker {
  display: flex;
  gap: 8px;
  margin-top: 16px;
  flex-wrap: wrap;
}

.color-option {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  cursor: pointer;
  border: 3px solid transparent;
  transition: transform 0.2s;
}

.color-option:hover {
  transform: scale(1.1);
}

.color-option.selected {
  border-color: white;
  box-shadow: 0 0 0 2px #333;
}
</style>